"""Import JSONL profiles generated by signalpost-starter-kit into Signalpost.

Usage (from ``backend``):
    python -m app.import_profiles ../path/to/profiles.jsonl
"""

import argparse
import gzip
import json
from datetime import datetime
from pathlib import Path
from typing import Any

from app.database import SessionLocal, init_db
from app.models.company import Company
from app.models.fact import Fact
from app.models.source import Source


def _timestamp(value: Any) -> datetime:
    if isinstance(value, str):
        try:
            return datetime.fromisoformat(value.replace("Z", "+00:00")).replace(tzinfo=None)
        except ValueError:
            pass
    return datetime.utcnow()


def _source_for(profile: dict[str, Any]) -> tuple[str, str, datetime]:
    evidence = profile.get("evidence") or {}
    records = evidence.values() if isinstance(evidence, dict) else evidence if isinstance(evidence, list) else []
    for record in records:
        if isinstance(record, dict) and record.get("source_url"):
            return str(record["source_url"]), str(record.get("source_class") or "Starter-kit source"), _timestamp(record.get("retrieved_at"))
    return "https://data.brreg.no/enhetsregisteret/api/", "Brønnøysundregistrene", datetime.utcnow()


def import_profile(db, row: dict[str, Any]) -> bool:
    profile = row.get("profile", row)
    org = str(profile.get("organisation_number") or profile.get("organization_number") or "")
    org = "".join(char for char in org if char.isdigit())
    name = profile.get("name")
    if len(org) != 9 or not name:
        return False

    company = db.query(Company).filter(Company.organization_number == org).first()
    if not company:
        company = Company(organization_number=org, name=str(name))
        db.add(company)
    company.name = str(name)
    company.company_type = profile.get("legal_form") or profile.get("company_type")
    company.status = "Active" if not profile.get("bankrupt") and not profile.get("liquidating") else "Inactive"
    company.municipality = profile.get("municipality")
    company.industry = profile.get("industry_label") or profile.get("industry")
    company.industry_code = profile.get("industry_code")
    website = profile.get("website")
    company.website = f"https://{website}" if website and not str(website).startswith("http") else website
    company.last_verified_at = datetime.utcnow()
    db.flush()

    source_url, source_name, retrieved_at = _source_for(profile)
    source = db.query(Source).filter(Source.company_id == company.id, Source.url == source_url).first()
    if not source:
        db.add(Source(company_id=company.id, url=source_url, name=source_name, retrieved_at=retrieved_at, http_status=200))

    excluded = {"organisation_number", "organization_number", "name", "legal_form", "company_type", "municipality", "website", "evidence", "raw"}
    for field, value in profile.items():
        if field in excluded or isinstance(value, (dict, list)) or value is None:
            continue
        fact = db.query(Fact).filter(Fact.company_id == company.id, Fact.field == field, Fact.source_url == source_url).first()
        if not fact:
            db.add(Fact(company_id=company.id, field=field, value=str(value), source_url=source_url,
                        source_name=source_name, retrieved_at=retrieved_at, confidence=0.9, verified=True))
    return True


def main() -> None:
    parser = argparse.ArgumentParser(description="Import signalpost-starter-kit profile JSONL")
    parser.add_argument("profiles", type=Path, help="JSONL output from run_competition_batch.py")
    args = parser.parse_args()
    init_db()
    imported = skipped = 0
    db = SessionLocal()
    try:
        opener = gzip.open if args.profiles.suffix == ".gz" else open
        with opener(args.profiles, "rt", encoding="utf-8") as profiles_file:
            lines = profiles_file.read().splitlines()
        for line in lines:
            if not line.strip():
                continue
            if import_profile(db, json.loads(line)):
                imported += 1
            else:
                skipped += 1
        db.commit()
    except Exception:
        db.rollback()
        raise
    finally:
        db.close()
    print(f"Imported {imported} profiles; skipped {skipped} invalid rows.")


if __name__ == "__main__":
    main()
